#define SECCOMP_FILTER_FLAG_NEW_LISTENER (1U << 0)

struct seccomp_notif_sizes {
    __u32 notif_size;
    __u32 notif_resp_size;
};

struct seccomp_notif_sizes sizes = {0};
int listener_fd;
long ret;

// Query supported notification structure sizes
ret = seccomp_unotify(0, 0, &sizes);

// Create the notification listener file descriptor
listener_fd = seccomp_unotify(
    SECCOMP_FILTER_FLAG_NEW_LISTENER,
    0,
    NULL
);

// Listener uses ioctls (RECV/SEND) on listener_fd
// Returns listener_fd or -1 on error (e.g., EINVAL)
